<script setup>
import { tr } from '../../../utils/i18n'
const props = defineProps({ modelValue: Array, columns: Array, create: Function, disabled: Boolean })
const emit = defineEmits(['update:modelValue'])
function add() { emit('update:modelValue', [...(props.modelValue || []), props.create ? props.create() : Object.fromEntries(props.columns.map(c => [c.key, c.type === 'boolean' ? false : c.type === 'number' ? 1 : '']))]) }
</script>
<template><div class="kwe-rows"><div v-for="(row, index) in modelValue" :key="index" class="kwe-row"><div v-for="column in columns" :key="column.key" class="kwe-cell"><label>{{ tr(column.label) }}</label><el-switch v-if="column.type === 'boolean'" v-model="row[column.key]" :disabled="disabled" /><el-input-number v-else-if="column.type === 'number'" v-model="row[column.key]" :min="column.min ?? 0" :max="column.max" :disabled="disabled" controls-position="right" /><el-select v-else-if="column.options" v-model="row[column.key]" filterable :allow-create="column.allowCreate" :disabled="disabled"><el-option v-for="option in column.options" :key="option" :value="option" :label="option" /></el-select><el-input v-else v-model="row[column.key]" :placeholder="column.placeholder" :disabled="disabled" /></div><el-button :disabled="disabled" link type="danger" @click="emit('update:modelValue', modelValue.filter((_, i) => i !== index))">{{ tr('删除') }}</el-button></div><el-button :disabled="disabled" plain size="small" @click="add">+ {{ tr('添加') }}</el-button></div></template>
<style scoped>.kwe-row{display:flex;align-items:end;gap:10px;padding:12px;background:#f8fafc;border:1px solid #e7edf4;border-radius:8px;margin-bottom:8px;flex-wrap:wrap}.kwe-cell{flex:1;min-width:100px}.kwe-cell label{display:block;font-size:12px;margin-bottom:6px;color:#64748b}.kwe-cell .el-select,.kwe-cell .el-input-number{width:100%}.kwe-row>.el-button{margin-bottom:8px}</style>
